package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import org.json.JSONObject;
import java.util.*;

/** Native monthly chart: touch and keyboard select a month; every value is also text. */
final class StatisticsView extends LinearLayout {
 private final StatisticsData data;private final LinearLayout chart;private final TextView detail,periodCaption,empty;
 private final HorizontalScrollView scroll;private final Button six,twelve;private int span=12;
 StatisticsView(Context c,JSONObject input,Runnable refresh,Runnable explore){
  super(c);setTag("statistics-view");setOrientation(VERTICAL);data=new StatisticsData(input);
  addView(text("SUA JORNADA EM NÚMEROS",11,NativeTheme.accent(c)));addView(text("Sua coleção, suas conclusões e o tempo registrado.",14,0xffbfc8d5));addView(text("Resumo geral da biblioteca",12,0xffbfc8d5));
  boolean single=c.getResources().getConfiguration().fontScale>1.3f||c.getResources().getConfiguration().screenWidthDp<360;int columns=single?1:2;
  String[] labels={"Títulos na coleção","Concluídos","Horas jogadas","Taxa de conclusão"},values={StatisticsData.integer(data.total),StatisticsData.integer(data.finished),StatisticsData.hours(data.hours),data.completion()<0?"—":data.completion()+"%"};int[] colors={NativeTheme.accent(c),0xff5fceae,0xffd4b579,0xff79b9e9};LinearLayout row=null;
  for(int i=0;i<4;i++){if(i%columns==0){row=new LinearLayout(c);addView(row);}LinearLayout metric=card();metric.setTag("stat-summary-"+i);metric.addView(text(labels[i],12,0xffbfc8d5));TextView value=text(values[i],29,colors[i]);value.setTypeface(null,Typeface.BOLD);metric.addView(value);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.setMargins(0,dp(6),i%columns<columns-1?dp(10):0,dp(6));row.addView(metric,lp);}
  if(data.total==0)addView(ScreenState.message(c,false,"Sua jornada começa na biblioteca","Adicione títulos e registre o progresso para acompanhar suas estatísticas.","Explorar biblioteca",explore));
  LinearLayout categories=card();categories.addView(heading("Sua coleção"));categories.addView(text("Distribuição por categoria",12,0xffbfc8d5));String[] names={"Jogos","Filmes","Séries","Animes"};long sum=0;for(int value:data.categories)sum+=value;int[] categoryColors={NativeTheme.accent(c),0xff79b9e9,0xffd4b579,0xffcc94dc};
  for(int i=0;i<names.length;i++){int pct=sum==0?0:(int)Math.round(data.categories[i]*100d/sum);categories.addView(text(names[i]+" · "+StatisticsData.integer(data.categories[i])+" · "+pct+"%",14,0xffedf2f8));ProgressBar track=new ProgressBar(c,null,android.R.attr.progressBarStyleHorizontal);track.setMax(1000);track.setProgress(sum==0?0:(int)Math.round(data.categories[i]*1000d/sum));track.setProgressTintList(android.content.res.ColorStateList.valueOf(categoryColors[i]));track.setContentDescription(names[i]+", "+StatisticsData.integer(data.categories[i])+", "+pct+"% da distribuição");categories.addView(track,new LinearLayout.LayoutParams(-1,dp(6)));}addView(categories);
  LinearLayout panel=card();panel.addView(heading("Seu ritmo, mês a mês"));panel.addView(text("Conclusões pela data de finalização registrada.",12,0xffbfc8d5));LinearLayout controls=new LinearLayout(c);controls.setOrientation(single?VERTICAL:HORIZONTAL);six=button("6 meses",()->{span=6;draw();});twelve=button("12 meses",()->{span=12;draw();});controls.addView(six,new LinearLayout.LayoutParams(single?-1:0,-2,single?0:1));controls.addView(twelve,new LinearLayout.LayoutParams(single?-1:0,-2,single?0:1));panel.addView(controls);
  TextView legend=text("● Jogos     ● Filmes, séries e animes",12,0xffbfc8d5);android.text.SpannableString legendText=new android.text.SpannableString(legend.getText());legendText.setSpan(new android.text.style.ForegroundColorSpan(NativeTheme.accent(c)),0,1,0);int dot=legend.getText().toString().lastIndexOf('●');legendText.setSpan(new android.text.style.ForegroundColorSpan(0xff53baa4),dot,dot+1,0);legend.setText(legendText);panel.addView(legend);
  periodCaption=text("",12,0xffbfc8d5);panel.addView(periodCaption);scroll=new HorizontalScrollView(c);scroll.setHorizontalScrollBarEnabled(false);chart=new LinearLayout(c);chart.setGravity(Gravity.BOTTOM);scroll.addView(chart,new HorizontalScrollView.LayoutParams(-2,-2));panel.addView(scroll,new LinearLayout.LayoutParams(-1,-2));empty=text("",13,0xffbfc8d5);panel.addView(empty);
  detail=text("",13,0xffedf2f8);detail.setTag("statistics-month-detail");detail.setAccessibilityLiveRegion(ACCESSIBILITY_LIVE_REGION_POLITE);detail.setPadding(dp(12),dp(12),dp(12),dp(12));detail.setBackground(AppStyle.shape(detail,NativeTheme.panelDark(c),12));panel.addView(detail);panel.addView(text("Selecione um mês para consultar os valores. Deslize o gráfico para ver os outros meses.",12,0xffbfc8d5));addView(panel);
  LinearLayout note=card();note.addView(text("Como ler seus dados",15,0xffedf2f8));note.addView(text("Concluídos sem data: "+StatisticsData.integer(data.undated)+". Esses títulos ficam fora do gráfico mensal. Platinados e favoritos contam como concluídos.",12,0xffbfc8d5));note.addView(text("As horas representam o total atual registrado nos jogos da biblioteca.",12,0xffbfc8d5));addView(note);addView(button("Atualizar estatísticas",refresh));draw();
 }
 private void draw(){
  java.util.List<StatisticsData.Month> months=data.period(span);six.setSelected(span==6);twelve.setSelected(span==12);AppStyle.button(six,span==6);AppStyle.button(twelve,span==12);six.setContentDescription("6 meses"+(span==6?", selecionado":""));twelve.setContentDescription("12 meses"+(span==12?", selecionado":""));chart.removeAllViews();long max=1,total=0;for(StatisticsData.Month m:months){max=Math.max(max,m.total());total+=m.total();}
  periodCaption.setText(months.isEmpty()?"Evolução mensal indisponível":months.get(0).shortLabel()+" a "+months.get(months.size()-1).shortLabel()+" · "+StatisticsData.integer(total)+(total==1?" conclusão":" conclusões"));empty.setVisibility(total>0?GONE:VISIBLE);empty.setText(months.isEmpty()?"O gráfico aparecerá quando houver dados mensais disponíveis.":"Nenhuma conclusão com data neste período.");
  for(StatisticsData.Month m:months){LinearLayout column=new LinearLayout(getContext());column.setOrientation(VERTICAL);column.setGravity(Gravity.CENTER_HORIZONTAL);column.setPadding(dp(4),dp(6),dp(4),dp(6));column.setTag("statistics-month-"+m.key);column.setFocusable(true);column.setContentDescription(m.label()+", "+m.detail());column.setBackground(AppStyle.interactive(column,NativeTheme.panelDark(getContext()),10));column.addView(new MonthBar(getContext(),m,max),new LinearLayout.LayoutParams(-1,dp(140)));TextView count=text(StatisticsData.integer(m.total()),12,0xffedf2f8);count.setGravity(Gravity.CENTER);count.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);column.addView(count);TextView label=text(m.shortLabel(),10,0xffbfc8d5);label.setGravity(Gravity.CENTER);label.setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);column.addView(label);chart.addView(column,new LinearLayout.LayoutParams(dp(56),-2));column.setOnClickListener(v->select(m));}
  if(months.isEmpty()){detail.setVisibility(GONE);}else{detail.setVisibility(VISIBLE);select(months.get(months.size()-1));scroll.post(()->scroll.fullScroll(FOCUS_RIGHT));}
 }
 private void select(StatisticsData.Month month){for(int i=0;i<chart.getChildCount();i++){View v=chart.getChildAt(i);boolean selected=("statistics-month-"+month.key).equals(v.getTag());v.setSelected(selected);v.setBackground(AppStyle.interactive(v,selected?NativeTheme.soft(getContext()):NativeTheme.panelDark(getContext()),10));}detail.setText(month.label()+"\n"+month.detail());}
 private static final class MonthBar extends View {
  private final StatisticsData.Month month;private final long maximum;private final Paint paint=new Paint(3);
  MonthBar(Context c,StatisticsData.Month month,long maximum){super(c);this.month=month;this.maximum=maximum;setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}
  protected void onDraw(Canvas canvas){super.onDraw(canvas);float bottom=getHeight()-NativeSheet.dp(getContext(),3),available=bottom-NativeSheet.dp(getContext(),6),left=getWidth()*.22f,right=getWidth()*.78f;paint.setColor(NativeTheme.soft(getContext()));canvas.drawRect(left,bottom,right,bottom+NativeSheet.dp(getContext(),1),paint);float games=(float)(available*month.games/maximum),media=(float)(available*month.media/maximum);paint.setColor(NativeTheme.accent(getContext()));canvas.drawRect(left,bottom-games,right,bottom,paint);paint.setColor(0xff53baa4);canvas.drawRect(left,bottom-games-media,right,bottom-games,paint);}
 }
 private LinearLayout card(){LinearLayout card=new LinearLayout(getContext());card.setOrientation(VERTICAL);card.setPadding(dp(16),dp(16),dp(16),dp(16));card.setBackground(AppStyle.surface(card,NativeTheme.panel(getContext()),18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(8),0,dp(8));card.setLayoutParams(lp);return card;}
 private TextView text(String value,int size,int color){return NativeSheet.text(getContext(),value,size,color);}
 private TextView heading(String value){TextView t=text(value,20,0xffedf2f8);t.setTypeface(null,Typeface.BOLD);return t;}
 private Button button(String label,Runnable action){Button b=new Button(getContext());b.setText(label);AppStyle.button(b,false);b.setMinHeight(dp(48));b.setOnClickListener(v->action.run());return b;}
 private int dp(int value){return NativeSheet.dp(getContext(),value);}
}
